function createConfigCommand() {
  const command = new Command("config").description("Inspect the framework configuration");
  command.command("effective").description(
    "Print, per knob, the value that actually binds, its source surface, and the gate that consumes it (consumed by: NOTHING flags a placebo). Read-only."
  ).option("--project-root <path>", "Project root", process.cwd()).option("--json", "emit machine-readable JSON").action((options) => {
    const knobs = resolveEffectiveConfig(options.projectRoot);
    if (options.json) {
      console.log(JSON.stringify({ knobs }, null, 2));
      return;
    }
    const keyWidth = Math.max(...knobs.map((knob) => knob.key.length));
    const valWidth = Math.max(...knobs.map((knob) => knob.value.length), 5);
    for (const knob of knobs) {
      console.log(
        `${knob.key.padEnd(keyWidth)}  ${knob.value.padEnd(valWidth)}  [${knob.surface}]  consumed by: ${knob.consumed_by}`
      );
    }
    const placebos = knobs.filter((knob) => knob.consumed_by === NOTHING).length;
    console.log(
      `
${knobs.length} knobs \xB7 ${placebos} with no consumer (placebo \u2014 no running code reads them).`
    );
  });
  return command;
}

